        response = self._request_operation('resumeGraphRun', path_params={ 'run_id': _required_path(run_id, 'run_id') }, headers={ 'Idempotency-Key': _require_idempotency_key(idempotency_key if idempotency_key is not None else _new_idempotency_key()) }, accept='application/json', body=dict(request))
