        response = self._request_operation('startTeamRun', headers={ 'Idempotency-Key': _require_idempotency_key(idempotency_key if idempotency_key is not None else _new_idempotency_key()) }, accept='application/json', body=dict(request))
        return cast(CommandReceipt, response_json(response))

